import React, { useState, useEffect, useRef, useCallback } from 'react';
import { DOC_INDEX, NAV, fetchDoc, searchIndex } from './useGithubDocs';
import { KB, findAnswer, SUGGESTED, SEED_USERS, SEED_TICKETS, AGENTS, SUPPORT_EMAIL } from './supportData';

// ── Theme ────────────────────────────────────────────────────────────────────
function useTheme() {
  const [dark, setDark] = useState(false);
  useEffect(() => { document.body.classList.toggle('dark', dark); }, [dark]);
  return [dark, () => setDark(d => !d)];
}

// ── Markdown renderer ────────────────────────────────────────────────────────
function esc(s) { return s.replace(/&/g,'&amp;').replace(/</g,'&lt;').replace(/>/g,'&gt;'); }
function inline(t) {
  return t
    .replace(/\*\*(.+?)\*\*/g,'<strong>$1</strong>')
    .replace(/\*(.+?)\*/g,'<em>$1</em>')
    .replace(/`(.+?)`/g,'<code>$1</code>')
    .replace(/\[(.+?)\]\(#(.+?)\)/g,'<a href="#" data-doc="$2" class="doc-lnk">$1 →</a>')
    .replace(/\[(.+?)\]\(mailto:(.+?)\)/g,'<a href="mailto:$2">$1</a>')
    .replace(/\[(.+?)\]\((.+?)\)/g,'<a href="$2" target="_blank" rel="noopener">$1</a>');
}
function renderMD(text) {
  if (!text) return '';
  const lines = text.split('\n');
  let html='', inCode=false, inTable=false, inList=false, lt='', inBq=false;
  const closeL=()=>{if(inList){html+=`</${lt}>`;inList=false;}};
  const closeBq=()=>{if(inBq){html+='</blockquote>';inBq=false;}};
  for (let i=0;i<lines.length;i++) {
    const line=lines[i];
    if(line.trim().startsWith('```')){
      if(inCode){html+='</code></pre>';inCode=false;}
      else{closeL();closeBq();html+='<pre><code>';inCode=true;}
      continue;
    }
    if(inCode){html+=esc(line)+'\n';continue;}
    if(inList&&!/^\s*[-*]\s|^\d+\.\s/.test(line)&&line.trim())closeL();
    if(inBq&&!line.startsWith('>'))closeBq();
    if(line.includes('|')&&line.trim().startsWith('|')){
      const cells=line.trim().split('|').filter((_,i2,a)=>i2>0&&i2<a.length-1);
      const isSep=cells.every(c=>c.trim().replace(/[-:]/g,'').trim()==='');
      if(isSep){if(!inTable){html+='<table>';inTable=true;}continue;}
      if(!inTable){html+='<table>';inTable=true;}
      const isH=lines[i+1]?.includes('---');
      const tag=isH?'th':'td';
      html+=`<tr>${cells.map(c=>`<${tag}>${inline(c.trim())}</${tag}>`).join('')}</tr>`;
      continue;
    } else if(inTable){html+='</table>';inTable=false;}
    const hm=line.match(/^(#{1,6})\s(.+)/);
    if(hm){closeL();closeBq();const lvl=hm[1].length;const id=hm[2].toLowerCase().replace(/[^a-z0-9\s]/g,'').trim().replace(/\s+/g,'-');html+=`<h${lvl} id="${id}">${inline(hm[2])}</h${lvl}>`;continue;}
    if(/^---+$/.test(line.trim())){closeL();closeBq();html+='<hr/>';continue;}
    if(line.startsWith('> ')){if(!inBq){html+='<blockquote>';inBq=true;}html+=`<p>${inline(line.slice(2))}</p>`;continue;}
    if(/^\s*[-*]\s/.test(line)){if(!inList||lt!=='ul'){closeL();html+='<ul>';inList=true;lt='ul';}html+=`<li>${inline(line.trim().slice(2))}</li>`;continue;}
    if(/^\s*\d+\.\s/.test(line)){if(!inList||lt!=='ol'){closeL();html+='<ol>';inList=true;lt='ol';}html+=`<li>${inline(line.replace(/^\s*\d+\.\s/,'').trim())}</li>`;continue;}
    if(line.trim()===''){closeL();closeBq();html+='<div class="sp"></div>';continue;}
    html+=`<p>${inline(line)}</p>`;
  }
  if(inCode)html+='</code></pre>';
  if(inTable)html+='</table>';
  if(inList)html+=`</${lt}>`;
  if(inBq)html+='</blockquote>';
  return html;
}
function extractTOC(c){return(c||'').split('\n').filter(l=>/^#{2,4}\s/.test(l)).map(l=>{const m=l.match(/^(#{2,4})\s(.+)/);return{level:m[1].length,text:m[2],id:m[2].toLowerCase().replace(/[^a-z0-9\s]/g,'').trim().replace(/\s+/g,'-')};});}

// ── UI helpers ────────────────────────────────────────────────────────────────
const PC={
  'CE Express':['#0077cc','#e8f3fc'],
  'CE Pro':    ['#059669','#ecfdf5'],
  'Both':      ['#d97706','#fffbeb'],
  'Training':  ['#7c3aed','#f5f3ff'],
};
const PI={'CE Express':'🌐','CE Pro':'🖥','Both':'🗺','Training':'🎓'};
const SC={'Open':'#d97706','In Progress':'#0077cc','Resolved':'#059669','Closed':'#6b7280'};
const PRIC={'Critical':'#dc2626','High':'#d97706','Normal':'#0077cc','Low':'#6b7280'};
const chip=(color,text)=><span style={{display:'inline-block',padding:'2px 8px',border:`1px solid ${color}44`,background:`${color}14`,color,fontFamily:'var(--font-mono)',fontSize:10,borderRadius:4,whiteSpace:'nowrap'}}>{text}</span>;
const now=()=>new Date().toLocaleTimeString([],{hour:'2-digit',minute:'2-digit'});
const btn=(label,onClick,style={})=><button onClick={onClick} style={{padding:'8px 16px',border:'1px solid var(--border)',borderRadius:6,background:'transparent',color:'var(--text)',cursor:'pointer',fontSize:13,...style}}>{label}</button>;
const pBtn=(label,onClick,style={})=><button onClick={onClick} style={{padding:'8px 16px',border:'none',borderRadius:6,background:'var(--accent)',color:'#fff',cursor:'pointer',fontSize:13,fontWeight:600,...style}}>{label}</button>;

// ── Article CSS ───────────────────────────────────────────────────────────────
const ART_CSS=`
  .art h1{font-size:24px;font-weight:700;color:var(--text-bright);letter-spacing:-0.02em;margin:0 0 6px}
  .art h2{font-size:18px;font-weight:600;color:var(--text-bright);margin:28px 0 10px;padding-top:8px;border-top:1px solid var(--border)}
  .art h3{font-size:15px;font-weight:600;color:var(--text-bright);margin:20px 0 7px}
  .art h4{font-size:12px;font-weight:600;color:var(--text-dim);margin:16px 0 5px;text-transform:uppercase;letter-spacing:.06em}
  .art p{margin:0 0 10px;line-height:1.75;color:var(--text)}
  .art .sp{height:6px}
  .art a{color:var(--accent);font-weight:500}
  .art a:hover{text-decoration:underline}
  .art strong{font-weight:600;color:var(--text-bright)}
  .art code{font-family:var(--font-mono);font-size:12px;background:var(--bg3);color:var(--text-bright);padding:2px 5px;border-radius:4px;border:1px solid var(--border)}
  .art pre{background:var(--bg4);color:var(--text-bright);padding:16px 18px;border-radius:8px;overflow-x:auto;margin:12px 0;font-size:12px;line-height:1.6;border:1px solid var(--border)}
  .art pre code{background:transparent;color:inherit;padding:0;border:none;font-size:inherit}
  .art table{width:100%;border-collapse:collapse;margin:12px 0;font-size:13px}
  .art th{background:var(--bg3);font-weight:600;color:var(--text-bright);text-align:left;padding:8px 11px;border:1px solid var(--border)}
  .art td{padding:7px 11px;border:1px solid var(--border);color:var(--text);vertical-align:top;line-height:1.6}
  .art tr:nth-child(even) td{background:var(--bg2)}
  .art ul,.art ol{padding-left:20px;margin:0 0 10px}
  .art li{margin:4px 0;line-height:1.65;color:var(--text)}
  .art blockquote{border-left:3px solid var(--accent);background:var(--accent-l);padding:10px 14px;margin:10px 0;border-radius:0 6px 6px 0;font-size:13px}
  .art blockquote p{margin:0;color:var(--text)}
  .art hr{border:none;border-top:1px solid var(--border);margin:20px 0}
  .doc-lnk{color:var(--accent);font-weight:500}
  @keyframes spin{to{transform:rotate(360deg)}}
  @keyframes tdot{0%,80%,100%{transform:translateY(0);opacity:.4}40%{transform:translateY(-5px);opacity:1}}
`;

// ════════════════════════════════════════════════════════════════════════════
export default function App() {
  const [dark, toggleDark] = useTheme();

  // ── View state ─────────────────────────────────────────────────────────
  // view: 'docs' | 'support'
  const [view, setView] = useState('docs');

  // ── Docs state ──────────────────────────────────────────────────────────
  const [activeDocId, setActiveDocId] = useState(null);
  const [doc,         setDoc]         = useState(null);
  const [docLoading,  setDocLoading]  = useState(false);
  const [searchQ,     setSearchQ]     = useState('');
  const [searchRes,   setSearchRes]   = useState([]);
  const [showSearch,  setShowSearch]  = useState(false);
  const [openSecs,    setOpenSecs]    = useState({});
  const [tocActive,   setTocActive]   = useState('');
  const searchRef = useRef(null);

  // ── Support state ───────────────────────────────────────────────────────
  const [currentUser, setCurrentUser] = useState(null);
  const [users,       setUsers]       = useState(SEED_USERS);
  const [tickets,     setTickets]     = useState(SEED_TICKETS);
  const [supportTab,  setSupportTab]  = useState('chat');  // chat|tickets|profile|adm-*
  const [loginEmail,  setLoginEmail]  = useState('');
  const [loginPass,   setLoginPass]   = useState('');
  const [loginErr,    setLoginErr]    = useState('');
  const [regMode,     setRegMode]     = useState(false);
  const [regName,     setRegName]     = useState('');
  const [regEmail,    setRegEmail]    = useState('');
  const [regCompany,  setRegCompany]  = useState('');
  const [regProduct,  setRegProduct]  = useState('CE Pro');
  // Chat
  const [messages,    setMessages]    = useState([]);
  const [chatInput,   setChatInput]   = useState('');
